import fs from "node:fs";
import path from "node:path";
import typia from "typia";

import type { IHumanActionParams } from "../IHumanActionParams";
import { HUMAN_LEXICON_FAMILIES } from "../lexicon/HUMAN_LEXICON_FAMILIES";
import type { IHumanLexiconParams } from "../lexicon/IHumanLexiconParams";

/**
 * Writes `src/lexicon/HUMAN_LEXICON_SCHEMAS.json`: the JSON schema of every
 * lexicon row's open parameters, by the row's registered name, and of every
 * action's parameters, by the action's name (`actions`), generated by
 * typia from the laws' own parameter types at compile time. Run by
 * `pnpm --filter @automovie/motions schemas`, which compiles this entry with
 * the typia transform; the first argument, when given, is the file to write
 * instead.
 *
 * @evidence contracts/development/common.md#meaningful-documentation States what is written, from what, by which command, and the argument.
 * @evidence contracts/development/implementation.md#principled-implementation typia's `json.schemas` reads the type the checker reads, so bounds and defaults come from each parameter's tags and meanings from its JSDoc. The type keys rows by family and export name; each export is paired at run time with the law it holds, whose `name` the row is registered under.
 * @evidence contracts/development/implementation.md#clear-and-simple-structure Generate, walk the families' namespaces, write.
 * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts Nothing is edited by hand: the file says which command writes it. Two laws of one family exported under one name, or two rows of one name, stop the generation with both named.
 * @evidenceExclude contracts/development/implementation.md#efficient-algorithms One generation per run.
 * @evidenceExclude contracts/development/implementation.md#reuse-equivalent-work Nothing to cache.
 * @evidenceExclude contracts/development/implementation.md#bound-retention-and-release-resources Runs once and exits.
 */
export function lexiconSchemas(target?: string): void {
  const collection: ReturnType<typeof typia.json.schemas> =
    typia.json.schemas<[IHumanLexiconParams, IHumanActionParams]>();
  type ISchema = { $ref?: string; properties?: Record<string, ISchema> };
  const components: Record<string, ISchema> = (collection.components.schemas ??
    {}) as Record<string, ISchema>;
  const resolved = (schema: ISchema | undefined): ISchema | undefined =>
    schema?.$ref === undefined
      ? schema
      : components[schema.$ref.split("/").at(-1)!];
  const families: Record<string, ISchema> =
    resolved(collection.schemas[0] as ISchema)?.properties ?? {};

  // Each export that plans, paired with the law it holds and so with the name the row is registered under.
  const rows: Map<string, ISchema> = new Map();
  for (const [family, spaces] of Object.entries(HUMAN_LEXICON_FAMILIES)) {
    const exports: Record<string, ISchema> =
      resolved(families[family])?.properties ?? {};
    const seen: Map<string, string> = new Map();
    for (const space of spaces as readonly object[])
      for (const [key, member] of Object.entries(space)) {
        if (
          typeof member !== "object" ||
          member === null ||
          !("plan" in member)
        )
          continue;
        const name: string = (member as { name: string }).name;
        if (seen.has(key) && seen.get(key) !== name)
          throw new Error(
            `${family}: two laws are exported as ${key} (${seen.get(key)} and ${name}); give one another export name`,
          );
        seen.set(key, name);
        if (
          rows.has(name) &&
          JSON.stringify(rows.get(name)) !== JSON.stringify(exports[key])
        )
          throw new Error(
            `two rows are named ${name} with different parameters`,
          );
        if (exports[key] !== undefined) rows.set(name, exports[key]!);
      }
  }
  const sorted = (entries: Map<string, ISchema>): Record<string, ISchema> =>
    Object.fromEntries(
      [...entries.entries()].sort(
        (a: [string, ISchema], b: [string, ISchema]): number =>
          a[0].localeCompare(b[0]),
      ),
    );
  const out: string =
    target ?? path.join(__dirname, "../lexicon/HUMAN_LEXICON_SCHEMAS.json");
  fs.writeFileSync(
    out,
    `${JSON.stringify(
      {
        $comment:
          "Written by `pnpm --filter @automovie/motions schemas` from the lexicon laws' parameter types (src/executable/lexiconSchemas.ts); do not edit by hand.",
        version: collection.version,
        rows: sorted(rows),
        actions: sorted(
          new Map(
            Object.entries(
              resolved(collection.schemas[1] as ISchema)?.properties ?? {},
            ),
          ),
        ),
        components: collection.components,
      },
      null,
      2,
    )}\n`,
  );
}

lexiconSchemas(process.argv[2]);
